script:
$name = {{SoftwareName}}
$paths = @(
  'HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*',
  'HKLM:\Software\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'
)
$app = Get-ItemProperty -Path $paths -ErrorAction SilentlyContinue | Where-Object { $_.DisplayName -like ('*' + $name + '*') } | Select-Object -First 1
if (-not $app) { Write-Error ('未找到已安装软件：' + $name); exit 2 }
$command = $app.QuietUninstallString
if (-not $command) { $command = $app.UninstallString }
if (-not $command) { Write-Error ('该软件未提供卸载命令：' + $app.DisplayName); exit 3 }
Write-Output ('执行卸载：' + $app.DisplayName)
cmd /c $command
Write-Output '卸载命令已执行完成。'

$target = {{Path}}
if (-not (Test-Path $target)) { Write-Error ('残留目录不存在：' + $target); exit 2 }
$items = Get-ChildItem -Path $target -Recurse -Force -ErrorAction SilentlyContinue
$size = ($items | Measure-Object -Property Length -Sum).Sum
if (-not $size) { $size = 0 }
Write-Output ('将清理 ' + $items.Count + ' 个对象，约 ' + [Math]::Round($size / 1MB, 1) + ' MB')
$items | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue
Write-Output '已清理软件残留目录内容。'
